questionvariables.text:
correct_answer:rand_selection([
[1, true, "The changing of structure of a population"],
[2, true, "The current size of a population"],
[3, true, "Population composition or structure"]],1);
incorrect_answers:rand_selection([
[4, false, "Carrying out population census"],
[5, false, "Producing Demographic health data"],
[6, false, "Infant deaths"],
[7, false, "Doing survey"]], 3);
ta: random_permutation(append(correct_answer,incorrect_answers));

ta_index: sort(makelist(x[1], x, ta));
ta_largest: last(ta_index);
